/bin/bash -lc "db='assets/data/career_path.db'
sqlite3 -readonly \""'$db" <<'"'SQL'
PRAGMA table_info(career_nodes);
SELECT id, slug, name, parent_id, stream_id FROM career_nodes ORDER BY id LIMIT 20;
WITH RECURSIVE tree(id, slug, name, parent_id, breadcrumb) AS (
  SELECT id, slug, name, parent_id, name FROM career_nodes WHERE parent_id IS NULL
  UNION ALL
  SELECT c.id, c.slug, c.name, c.parent_id, tree.breadcrumb || ' > ' || c.name
  FROM career_nodes c JOIN tree ON c.parent_id = tree.id
)
SELECT id, slug, breadcrumb FROM tree WHERE lower(breadcrumb) LIKE '%arts%' OR lower(breadcrumb) LIKE '%commerce%' OR lower(breadcrumb) LIKE '%science%' LIMIT 30;
SQL"

/bin/bash -lc "db='assets/data/career_path.db'
sqlite3 -readonly \""'$db" <<'"'SQL'
PRAGMA table_info(career_nodes);
SELECT id, slug, name, parent_id, stream_id FROM career_nodes ORDER BY id LIMIT 20;
WITH RECURSIVE tree(id, slug, name, parent_id, breadcrumb) AS (
  SELECT id, slug, name, parent_id, name FROM career_nodes WHERE parent_id IS NULL
  UNION ALL
  SELECT c.id, c.slug, c.name, c.parent_id, tree.breadcrumb || ' > ' || c.name
  FROM career_nodes c JOIN tree ON c.parent_id = tree.id
)
SELECT id, slug, breadcrumb FROM tree WHERE lower(breadcrumb) LIKE '%arts%' OR lower(breadcrumb) LIKE '%commerce%' OR lower(breadcrumb) LIKE '%science%' LIMIT 30;
SQL"
